const input = $json.department || "";
const value = input.toLowerCase().trim();

let department = input;

const mappings = [
  { keywords: ["ortho", "orthopedic", "orthopedics", "bone", "joint", "fracture", "knee", "back pain"], department: "Orthopedics" },
  { keywords: ["child", "children", "baby", "kid", "kids", "pediatric", "pediatrics"], department: "Pediatrics" },
  { keywords: ["skin", "rash", "acne", "allergy", "itching"], department: "Dermatology" },
  { keywords: ["heart", "cardio", "chest pain", "bp", "blood pressure"], department: "Cardiology" },
  { keywords: ["eye", "vision", "blurry", "ophthalmology"], department: "Ophthalmology" },
  { keywords: ["tooth", "teeth", "dental", "dentist"], department: "Dentistry" },
  { keywords: ["fever", "cold", "cough", "weakness", "general", "checkup"], department: "General Medicine" }
];

for (const item of mappings) {
  if (item.keywords.some(keyword => value.includes(keyword))) {
    department = item.department;
    break;
  }
}

return [
  {
    json: {
      original_input: input,
      department
    }
  }
];

const doctors = items.map(item => item.json);

if (doctors.length === 0) {
  return [
    {
      json: {
        found: false,
        count: 0,
        department: "",
        doctors: [],
        message: "No active doctors found."
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      count: doctors.length,
      department: doctors[0].department,
      doctors: doctors.map(d => ({
        doctor_id: d.doctor_id,
        doctor_name: d.doctor_name,
        specialization: d.specialization,
        department: d.department,
        consultation_duration: d.consultation_duration,
        available_from: d.available_from,
        available_to: d.available_to
      })),
      message: `${doctors.length} doctor(s) found in ${doctors[0].department}.`
    }
  }
];
